-- GENERATED by db/build-init.mjs from db/data/. Do not edit by hand.
-- BigQuery (GoogleSQL) script. Safe to re-run: the catalogue tables are replaced,
-- the order tables (pedidos, pedido_lineas) are only created if missing.
-- Products: 53 for sale. Discontinued and excluded: A-2337, B-82541, B-21589, B-94642.

CREATE SCHEMA IF NOT EXISTS `devoshop` OPTIONS (location = 'europe-southwest1');

CREATE OR REPLACE TABLE `devoshop.productos` (
    sku          STRING        NOT NULL,
    nombre       STRING        NOT NULL,
    descripcion  STRING,                                -- texto del proveedor B, si lo hay
    categoria    STRING        NOT NULL,                -- sofa, cama, colchon, mesa, silla, escritorio, silla_oficina, almacenaje, iluminacion, textil, accesorio
    precio       NUMERIC(10,2) NOT NULL,                -- EUR, IVA 21 % incluido
    plazas       INT64,                                 -- solo sofás y sillones
    ancho_cm     NUMERIC(7,2)  NOT NULL,
    fondo_cm     NUMERIC(7,2)  NOT NULL,
    alto_cm      NUMERIC(7,2)  NOT NULL,
    color        STRING        NOT NULL,                -- blanco, negro, gris, beige, marron, azul, verde, roble, nogal, natural
    material     STRING        NOT NULL,                -- tela, lino, piel, terciopelo, madera, metal, melamina, espuma, muelles, algodon, lana, malla, ceramica
    stock        INT64,                                 -- NULL = desconocido
    actualizado  TIMESTAMP     NOT NULL,                -- fecha del registro ganador
    PRIMARY KEY (sku) NOT ENFORCED
);

-- Supplier identifiers of each product (ids_origen in /catalogo.json).
CREATE OR REPLACE TABLE `devoshop.producto_origenes` (
    id_origen    STRING NOT NULL,
    sku          STRING NOT NULL,
    PRIMARY KEY (id_origen) NOT ENFORCED
);

-- Past orders of a similar store, for "frequently bought together".
-- id_origen is a supplier id; join through producto_origenes to get the sku.
CREATE OR REPLACE TABLE `devoshop.historial_ventas` (
    pedido           STRING        NOT NULL,
    fecha            DATE          NOT NULL,
    id_origen        STRING        NOT NULL,
    cantidad         INT64         NOT NULL,
    precio_unitario  NUMERIC(10,2) NOT NULL
);

-- Sales conditions (data/condiciones-de-venta.md) as values the checkout can use.
CREATE OR REPLACE TABLE `devoshop.condiciones` (
    clave        STRING NOT NULL,
    valor        STRING NOT NULL,
    descripcion  STRING NOT NULL,
    PRIMARY KEY (clave) NOT ENFORCED
);

-- Orders placed in this store. Kept across re-runs.
CREATE TABLE IF NOT EXISTS `devoshop.pedidos` (
    order_id     STRING        NOT NULL,                -- UUID
    email        STRING        NOT NULL,
    estado       STRING        DEFAULT 'completed' NOT NULL, -- pending, completed, cancelled
    subtotal     NUMERIC(10,2) NOT NULL,
    envio        NUMERIC(10,2) DEFAULT 0 NOT NULL,
    montaje      NUMERIC(10,2) DEFAULT 0 NOT NULL,
    total        NUMERIC(10,2) NOT NULL,
    creado       TIMESTAMP     DEFAULT CURRENT_TIMESTAMP() NOT NULL,
    PRIMARY KEY (order_id) NOT ENFORCED
);

CREATE TABLE IF NOT EXISTS `devoshop.pedido_lineas` (
    order_id     STRING        NOT NULL,
    sku          STRING        NOT NULL,
    cantidad     INT64         NOT NULL,
    precio       NUMERIC(10,2) NOT NULL,
    PRIMARY KEY (order_id, sku) NOT ENFORCED
);






-- Exactly what GET /catalogo.json publishes: SELECT catalogo FROM devoshop.catalogo_json;
CREATE OR REPLACE VIEW `devoshop.catalogo_json` AS
SELECT TO_JSON_STRING(STRUCT(ARRAY(
           SELECT AS STRUCT
               p.sku,
               ARRAY(SELECT o.id_origen FROM `devoshop.producto_origenes` o WHERE o.sku = p.sku ORDER BY o.id_origen) AS ids_origen,
               p.nombre,
               p.categoria,
               p.precio,
               p.plazas,
               p.ancho_cm,
               p.color,
               p.material
           FROM `devoshop.productos` p
           ORDER BY p.categoria, p.nombre
       ) AS productos)) AS catalogo;

-- Products bought together in the sales history, mapped to our skus.
-- SELECT * FROM devoshop.comprado_junto WHERE sku = 'sofa-nordico' ORDER BY pedidos DESC LIMIT 4;
CREATE OR REPLACE VIEW `devoshop.comprado_junto` AS
WITH lineas AS (
    SELECT DISTINCT h.pedido, o.sku
    FROM `devoshop.historial_ventas` h
    JOIN `devoshop.producto_origenes` o ON o.id_origen = h.id_origen
)
SELECT a.sku, b.sku AS sku_junto, COUNT(*) AS pedidos
FROM lineas a
JOIN lineas b ON a.pedido = b.pedido AND a.sku <> b.sku
GROUP BY a.sku, b.sku;
